payload_mode = SERIALIZATION_READY
stream_carrier = display_stream
thinking_bypass = ACTIVE`,conditions:{nl:"any",comic:"any",backend:"any",slotRewrite:"any"},trigger:{mode:"always",orWords:[],andWords:[]}},{id:"entry_tool_guide_6",name:"【ToolCall引导】执行唤醒",enabled:!0,role:"user",entryType:"tool_guide",content:`//* ============================================================================= *//
